+function calc(name, date, time, loc) {
+  const s = `${name}|${date}|${time}|${loc}`;
+  let h = 0;
+  for (let i = 0; i < s.length; i += 1) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
+  return { sun: sign(h), moon: sign(h >> 2), rising: sign(h >> 4) };
+}
+
+function getLocationMatches(rawValue) {
+  const q = rawValue.trim().toLowerCase();
+  if (!q) return [];
+  const prefix = [];
+  const contains = [];
+  for (const item of LOCATION_DATA) {
+    const normalized = item.toLowerCase();
+    if (normalized.startsWith(q)) {
+      prefix.push(item);
+    } else if (normalized.includes(q)) {
+      contains.push(item);
+    }
+  }
+  return prefix.concat(contains).slice(0, 10);
+}
+
+function wireLocationAutocomplete(input) {
+  if (!input) return;
+  const wrapper = document.createElement("div");
+  wrapper.className = "loc-autocomplete";
+  input.parentNode.insertBefore(wrapper, input);
+  wrapper.appendChild(input);
+
+  const list = document.createElement("ul");
+  list.className = "loc-suggestions";
+  list.setAttribute("role", "listbox");
+  wrapper.appendChild(list);
+
+  let selectedIndex = -1;
+  let activeItems = [];
+
+  function closeSuggestions() {
+    list.classList.remove("open");
+    list.innerHTML = "";
+    activeItems = [];
+    selectedIndex = -1;
+  }
+
+  function commitSelection(value) {
+    input.value = value;
+    closeSuggestions();
+  }
+
+  function highlightActive() {
+    const options = list.querySelectorAll(".loc-option");
+    options.forEach((option, idx) => {
+      option.classList.toggle("active", idx === selectedIndex);
+      if (idx === selectedIndex) option.scrollIntoView({ block: "nearest" });
+    });
+  }
+
+  function renderSuggestions() {
+    activeItems = getLocationMatches(input.value);
+    list.innerHTML = "";
+    selectedIndex = -1;
+    if (!activeItems.length) {
+      closeSuggestions();
+      return;
+    }
+    activeItems.forEach((item, idx) => {
+      const li = document.createElement("li");
+      li.className = "loc-option";
+      li.setAttribute("role", "option");
+      li.dataset.index = String(idx);
+      li.textContent = item;
+      li.addEventListener("mousedown", (event) => {
+        event.preventDefault();
+        commitSelection(item);
+      });
+      list.appendChild(li);
+    });
+    list.classList.add("open");
+  }
+
+  input.addEventListener("input", renderSuggestions);
+  input.addEventListener("keydown", (event) => {
+    if (!list.classList.contains("open") && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
+      renderSuggestions();
+    }
+    if (!list.classList.contains("open")) return;
+    if (event.key === "ArrowDown") {
+      event.preventDefault();
+      selectedIndex = Math.min(selectedIndex + 1, activeItems.length - 1);
+      highlightActive();
+    } else if (event.key === "ArrowUp") {
+      event.preventDefault();
+      selectedIndex = Math.max(selectedIndex - 1, 0);
+      highlightActive();
+    } else if (event.key === "Enter") {
+      if (selectedIndex >= 0 && activeItems[selectedIndex]) {
+        event.preventDefault();
+        commitSelection(activeItems[selectedIndex]);
+      }
+    } else if (event.key === "Escape") {
+      closeSuggestions();
+    }
+  });
+
+  input.addEventListener("blur", () => {
+    window.setTimeout(closeSuggestions, 100);
+  });
+}
+
+function wireCalculator(root) {
+  if (!root) return;
+  const form = root.querySelector("form");
+  const name = root.querySelector("[name=name]");
+  const date = root.querySelector("[name=dob]");
+  const time = root.querySelector("[name=tob]");
+  const loc = root.querySelector("[name=loc]");
+  const out = root.querySelector(".results");
+  const sun = root.querySelector("[data-sun]");
+  const moon = root.querySelector("[data-moon]");
+  const rising = root.querySelector("[data-rising]");
+
+  wireLocationAutocomplete(loc);
+
+  form?.addEventListener("submit", (e) => {
+    e.preventDefault();
+    if (!name?.value.trim() || !date.value || !time.value || !loc.value.trim()) {
+      alert("Please fill your name, date, birth time, and location.");
+      return;
+    }
+    const r = calc(name.value.trim(), date.value, time.value, loc.value.trim());
+    if (sun) sun.textContent = r.sun;
+    if (moon) moon.textContent = r.moon;
+    if (rising) rising.textContent = r.rising;
+    out?.classList.add("show");
+  });
+}
+
+document.addEventListener("DOMContentLoaded", () => {
+  document.querySelectorAll("[data-calc-root]").forEach((root) => wireCalculator(root));
+  document.querySelectorAll("[data-year]").forEach((el) => {
+    el.textContent = new Date().getFullYear();
+  });
+});
